<template><div><h1 id="活动系统核心实现详解" tabindex="-1"><a class="header-anchor" href="#活动系统核心实现详解"><span>活动系统核心实现详解</span></a></h1>
<p>本文档详细描述活动系统三大核心组件的具体实现。</p>
<h2 id="目录" tabindex="-1"><a class="header-anchor" href="#目录"><span>目录</span></a></h2>
<ol>
<li><a href="#1-%E8%A7%A6%E5%8F%91%E5%99%A8%E5%BC%95%E6%93%8E-trigger-engine">触发器引擎 (Trigger Engine)</a></li>
<li><a href="#2-%E6%9D%A1%E4%BB%B6%E8%AF%84%E4%BC%B0%E5%99%A8-condition-evaluator">条件评估器 (Condition Evaluator)</a></li>
<li><a href="#3-%E5%8A%A8%E4%BD%9C%E6%89%A7%E8%A1%8C%E5%99%A8-action-executor">动作执行器 (Action Executor)</a></li>
</ol>
<hr>
<h2 id="_1-触发器引擎-trigger-engine" tabindex="-1"><a class="header-anchor" href="#_1-触发器引擎-trigger-engine"><span>1. 触发器引擎 (Trigger Engine)</span></a></h2>
<h3 id="_1-1-核心接口定义" tabindex="-1"><a class="header-anchor" href="#_1-1-核心接口定义"><span>1.1 核心接口定义</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/matcher.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Event 统一事件结构</span></span>
<span class="line"><span class="token keyword">type</span> Event <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 基础字段</span></span>
<span class="line">    EventID    <span class="token builtin">string</span>                 <span class="token string">`json:"event_id"`</span></span>
<span class="line">    EventType  <span class="token builtin">string</span>                 <span class="token string">`json:"event_type"`</span></span>
<span class="line">    PlayerID   <span class="token builtin">string</span>                 <span class="token string">`json:"player_id"`</span></span>
<span class="line">    GameID     <span class="token builtin">string</span>                 <span class="token string">`json:"game_id"`</span></span>
<span class="line">    Env        <span class="token builtin">string</span>                 <span class="token string">`json:"env"`</span></span>
<span class="line">    ServerID   <span class="token builtin">string</span>                 <span class="token string">`json:"server_id"`</span></span>
<span class="line">    SessionID  <span class="token builtin">string</span>                 <span class="token string">`json:"session_id"`</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 时间</span></span>
<span class="line">    EventTime  time<span class="token punctuation">.</span>Time              <span class="token string">`json:"event_time"`</span></span>
<span class="line">    ReceiveTime time<span class="token punctuation">.</span>Time             <span class="token string">`json:"receive_time"`</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 上下文</span></span>
<span class="line">    Platform   <span class="token builtin">string</span>                 <span class="token string">`json:"platform"`</span>    <span class="token comment">// ios/android/web/pc</span></span>
<span class="line">    Channel    <span class="token builtin">string</span>                 <span class="token string">`json:"channel"`</span></span>
<span class="line">    Country    <span class="token builtin">string</span>                 <span class="token string">`json:"country"`</span></span>
<span class="line">    Region     <span class="token builtin">string</span>                 <span class="token string">`json:"region"`</span></span>
<span class="line">    DeviceID   <span class="token builtin">string</span>                 <span class="token string">`json:"device_id"`</span></span>
<span class="line">    AppVersion <span class="token builtin">string</span>                 <span class="token string">`json:"app_version"`</span></span>
<span class="line">    IP         <span class="token builtin">string</span>                 <span class="token string">`json:"ip"`</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 事件属性 (动态)</span></span>
<span class="line">    Properties <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token string">`json:"properties"`</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 扩展</span></span>
<span class="line">    Context    <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token string">`json:"context"`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Matcher 匹配器接口</span></span>
<span class="line"><span class="token keyword">type</span> Matcher <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Match 匹配事件到活动</span></span>
<span class="line">    <span class="token function">Match</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> event Event<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>MatchResult<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// MatchByID 匹配特定活动</span></span>
<span class="line">    <span class="token function">MatchByID</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> campaignID <span class="token builtin">string</span><span class="token punctuation">,</span> event Event<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>MatchResult<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// MatchResult 匹配结果</span></span>
<span class="line"><span class="token keyword">type</span> MatchResult <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    CampaignID   <span class="token builtin">string</span></span>
<span class="line">    TemplateID   <span class="token builtin">string</span></span>
<span class="line">    Priority     <span class="token builtin">int32</span></span>
<span class="line">    MatchReason  <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span>  <span class="token comment">// 匹配原因（用于调试）</span></span>
<span class="line">    MatchedAt    time<span class="token punctuation">.</span>Time</span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 缓存的匹配数据，供后续使用</span></span>
<span class="line">    PlayerInfo   <span class="token operator">*</span>PlayerSnapshot</span>
<span class="line">    ContextData  <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// PlayerSnapshot 玩家快照</span></span>
<span class="line"><span class="token keyword">type</span> PlayerSnapshot <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    PlayerID       <span class="token builtin">string</span></span>
<span class="line">    Level          <span class="token builtin">int32</span></span>
<span class="line">    VIPLevel       <span class="token builtin">int32</span></span>
<span class="line">    RegisterTime   time<span class="token punctuation">.</span>Time</span>
<span class="line">    TotalRecharge  <span class="token builtin">int64</span></span>
<span class="line">    LastLoginTime  time<span class="token punctuation">.</span>Time</span>
<span class="line">    OnlineDuration <span class="token builtin">int64</span>  <span class="token comment">// 秒</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 扩展属性</span></span>
<span class="line">    Attributes     <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-2-触发器匹配器实现" tabindex="-1"><a class="header-anchor" href="#_1-2-触发器匹配器实现"><span>1.2 触发器匹配器实现</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/trigger_matcher.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"fmt"</span></span>
<span class="line">    <span class="token string">"log/slog"</span></span>
<span class="line">    <span class="token string">"sync"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/cache"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/service/playersvc"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// TriggerMatcher 触发器匹配器</span></span>
<span class="line"><span class="token keyword">type</span> TriggerMatcher <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    cache        cache<span class="token punctuation">.</span>CampaignCache</span>
<span class="line">    playerSvc    playersvc<span class="token punctuation">.</span>PlayerService</span>
<span class="line">    freqLimiter  FrequencyLimiter</span>
<span class="line">    logger       <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger</span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 配置</span></span>
<span class="line">    maxConcurrent <span class="token builtin">int</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// FrequencyLimiter 频率限制器接口</span></span>
<span class="line"><span class="token keyword">type</span> FrequencyLimiter <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">Check</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> scope <span class="token builtin">string</span><span class="token punctuation">,</span> key <span class="token builtin">string</span><span class="token punctuation">,</span> limit <span class="token builtin">int</span><span class="token punctuation">,</span> window <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">Record</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> scope <span class="token builtin">string</span><span class="token punctuation">,</span> key <span class="token builtin">string</span><span class="token punctuation">,</span> window <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// NewTriggerMatcher 创建触发器匹配器</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewTriggerMatcher</span><span class="token punctuation">(</span></span>
<span class="line">    cache cache<span class="token punctuation">.</span>CampaignCache<span class="token punctuation">,</span></span>
<span class="line">    playerSvc playersvc<span class="token punctuation">.</span>PlayerService<span class="token punctuation">,</span></span>
<span class="line">    freqLimiter FrequencyLimiter<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token operator">*</span>TriggerMatcher <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>TriggerMatcher<span class="token punctuation">{</span></span>
<span class="line">        cache<span class="token punctuation">:</span>         cache<span class="token punctuation">,</span></span>
<span class="line">        playerSvc<span class="token punctuation">:</span>     playerSvc<span class="token punctuation">,</span></span>
<span class="line">        freqLimiter<span class="token punctuation">:</span>   freqLimiter<span class="token punctuation">,</span></span>
<span class="line">        logger<span class="token punctuation">:</span>        slog<span class="token punctuation">.</span><span class="token function">Default</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        maxConcurrent<span class="token punctuation">:</span> <span class="token number">100</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Match 匹配事件到所有活动</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>tm <span class="token operator">*</span>TriggerMatcher<span class="token punctuation">)</span> <span class="token function">Match</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> event Event<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>MatchResult<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    startTime <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">defer</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        tm<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Debug</span><span class="token punctuation">(</span><span class="token string">"trigger_match_completed"</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"event_type"</span><span class="token punctuation">,</span> event<span class="token punctuation">.</span>EventType<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"player_id"</span><span class="token punctuation">,</span> event<span class="token punctuation">.</span>PlayerID<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"duration_ms"</span><span class="token punctuation">,</span> time<span class="token punctuation">.</span><span class="token function">Since</span><span class="token punctuation">(</span>startTime<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Milliseconds</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 1. 获取所有活动活动实例</span></span>
<span class="line">    campaigns<span class="token punctuation">,</span> err <span class="token operator">:=</span> tm<span class="token punctuation">.</span>cache<span class="token punctuation">.</span><span class="token function">GetActiveCampaigns</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> event<span class="token punctuation">.</span>GameID<span class="token punctuation">,</span> event<span class="token punctuation">.</span>Env<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"get active campaigns: %w"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>campaigns<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 并发匹配（控制并发数）</span></span>
<span class="line">    results <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>MatchResult<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">len</span><span class="token punctuation">(</span>campaigns<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    resultChan <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">chan</span> <span class="token operator">*</span>MatchResult<span class="token punctuation">,</span> <span class="token function">len</span><span class="token punctuation">(</span>campaigns<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    errorChan <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">chan</span> <span class="token builtin">error</span><span class="token punctuation">,</span> <span class="token function">len</span><span class="token punctuation">(</span>campaigns<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    sem <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">chan</span> <span class="token keyword">struct</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> tm<span class="token punctuation">.</span>maxConcurrent<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> campaign <span class="token operator">:=</span> <span class="token keyword">range</span> campaigns <span class="token punctuation">{</span></span>
<span class="line">        sem <span class="token operator">&lt;-</span> <span class="token keyword">struct</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">go</span> <span class="token keyword">func</span><span class="token punctuation">(</span>c <span class="token operator">*</span>types<span class="token punctuation">.</span>CampaignInstance<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">defer</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">&lt;-</span>sem <span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
