<span class="line">        <span class="token keyword">return</span> now<span class="token punctuation">.</span><span class="token function">After</span><span class="token punctuation">(</span>window<span class="token punctuation">.</span>StartTime<span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> now<span class="token punctuation">.</span><span class="token function">Before</span><span class="token punctuation">(</span>window<span class="token punctuation">.</span>EndTime<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"rolling"</span><span class="token punctuation">:</span></span>
