<span class="line">        firstTrigger<span class="token punctuation">,</span> err <span class="token operator">:=</span> tm<span class="token punctuation">.</span><span class="token function">getFirstTriggerTime</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> event<span class="token punctuation">.</span>PlayerID<span class="token punctuation">,</span> window<span class="token punctuation">.</span>StartTime<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        duration <span class="token operator">:=</span> now<span class="token punctuation">.</span><span class="token function">Sub</span><span class="token punctuation">(</span>firstTrigger<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> duration <span class="token operator">&lt;</span> window<span class="token punctuation">.</span>EndTime<span class="token punctuation">.</span><span class="token function">Sub</span><span class="token punctuation">(</span>window<span class="token punctuation">.</span>StartTime<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"daily"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 每日窗口：每天特定时间段</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token operator">!</span>tm<span class="token punctuation">.</span><span class="token function">isInActivePeriod</span><span class="token punctuation">(</span>now<span class="token punctuation">,</span> window<span class="token punctuation">.</span>StartTime<span class="token punctuation">,</span> window<span class="token punctuation">.</span>EndTime<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">if</span> window<span class="token punctuation">.</span>DayStart <span class="token operator">!=</span> <span class="token string">""</span> <span class="token operator">||</span> window<span class="token punctuation">.</span>DayEnd <span class="token operator">!=</span> <span class="token string">""</span> <span class="token punctuation">{</span></span>
<span class="line">            dayStart <span class="token operator">:=</span> tm<span class="token punctuation">.</span><span class="token function">parseTimeOfDay</span><span class="token punctuation">(</span>window<span class="token punctuation">.</span>DayStart<span class="token punctuation">)</span></span>
<span class="line">            dayEnd <span class="token operator">:=</span> tm<span class="token punctuation">.</span><span class="token function">parseTimeOfDay</span><span class="token punctuation">(</span>window<span class="token punctuation">.</span>DayEnd<span class="token punctuation">)</span></span>
<span class="line">            current <span class="token operator">:=</span> tm<span class="token punctuation">.</span><span class="token function">timeOfDay</span><span class="token punctuation">(</span>now<span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">return</span> current <span class="token operator">>=</span> dayStart <span class="token operator">&amp;&amp;</span> current <span class="token operator">&lt;=</span> dayEnd</span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span></span>
