<span class="line">                weekday <span class="token operator">=</span> <span class="token number">6</span></span>
<span class="line">            <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">                weekday <span class="token operator">-=</span> <span class="token number">1</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token operator">!</span>tm<span class="token punctuation">.</span><span class="token function">containsInt</span><span class="token punctuation">(</span>window<span class="token punctuation">.</span>WeekDays<span class="token punctuation">,</span> weekday<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> tm<span class="token punctuation">.</span><span class="token function">isInActivePeriod</span><span class="token punctuation">(</span>now<span class="token punctuation">,</span> window<span class="token punctuation">.</span>StartTime<span class="token punctuation">,</span> window<span class="token punctuation">.</span>EndTime<span class="token punctuation">)</span></span>
<span class="line"></span>
