<span class="line">        <span class="token comment">// 每月窗口：每月特定日期</span></span>
<span class="line">        dayOfMonth <span class="token operator">:=</span> now<span class="token punctuation">.</span><span class="token function">Day</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>window<span class="token punctuation">.</span>DaysOfMonth<span class="token punctuation">)</span> <span class="token operator">></span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
