<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>tm <span class="token operator">*</span>TriggerMatcher<span class="token punctuation">)</span> <span class="token function">containsString</span><span class="token punctuation">(</span>slice <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">,</span> v <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> item <span class="token operator">:=</span> <span class="token keyword">range</span> slice <span class="token punctuation">{</span></span>
