<span class="line">            <span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// checkRegisterTime 检查注册时间</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>tm <span class="token operator">*</span>TriggerMatcher<span class="token punctuation">)</span> <span class="token function">checkRegisterTime</span><span class="token punctuation">(</span>registerTime time<span class="token punctuation">.</span>Time<span class="token punctuation">,</span> after<span class="token punctuation">,</span> before <span class="token operator">*</span>time<span class="token punctuation">.</span>Time<span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> after <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> registerTime<span class="token punctuation">.</span><span class="token function">Before</span><span class="token punctuation">(</span><span class="token operator">*</span>after<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">if</span> before <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> registerTime<span class="token punctuation">.</span><span class="token function">After</span><span class="token punctuation">(</span><span class="token operator">*</span>before<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// checkFrequencyLimit 检查频率限制</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>tm <span class="token operator">*</span>TriggerMatcher<span class="token punctuation">)</span> <span class="token function">checkFrequencyLimit</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> campaign <span class="token operator">*</span>types<span class="token punctuation">.</span>CampaignInstance<span class="token punctuation">,</span> event Event<span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token builtin">cap</span> <span class="token operator">:=</span> campaign<span class="token punctuation">.</span>TriggerConfig<span class="token punctuation">.</span>FrequencyCap</span>
<span class="line">    <span class="token keyword">if</span> <span class="token builtin">cap</span> <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token operator">||</span> <span class="token builtin">cap</span><span class="token punctuation">.</span>MaxCount <span class="token operator">&lt;</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span> <span class="token comment">// 无限制</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 构建限制键</span></span>
<span class="line">    <span class="token keyword">var</span> key <span class="token builtin">string</span></span>
<span class="line">    <span class="token keyword">switch</span> <span class="token builtin">cap</span><span class="token punctuation">.</span>Scope <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"global"</span><span class="token punctuation">:</span></span>
<span class="line">        key <span class="token operator">=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"global:%s"</span><span class="token punctuation">,</span> campaign<span class="token punctuation">.</span>ID<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"player"</span><span class="token punctuation">:</span></span>
<span class="line">        key <span class="token operator">=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"player:%s:%s"</span><span class="token punctuation">,</span> campaign<span class="token punctuation">.</span>ID<span class="token punctuation">,</span> event<span class="token punctuation">.</span>PlayerID<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"server"</span><span class="token punctuation">:</span></span>
<span class="line">        key <span class="token operator">=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"server:%s:%s"</span><span class="token punctuation">,</span> campaign<span class="token punctuation">.</span>ID<span class="token punctuation">,</span> event<span class="token punctuation">.</span>ServerID<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"campaign"</span><span class="token punctuation">:</span></span>
<span class="line">        key <span class="token operator">=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"campaign:%s:%s"</span><span class="token punctuation">,</span> campaign<span class="token punctuation">.</span>ID<span class="token punctuation">,</span> event<span class="token punctuation">.</span>PlayerID<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">default</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 检查限制</span></span>
<span class="line">    allowed<span class="token punctuation">,</span> err <span class="token operator">:=</span> tm<span class="token punctuation">.</span>freqLimiter<span class="token punctuation">.</span><span class="token function">Check</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token builtin">cap</span><span class="token punctuation">.</span>Scope<span class="token punctuation">,</span> key<span class="token punctuation">,</span> <span class="token builtin">cap</span><span class="token punctuation">.</span>MaxCount<span class="token punctuation">,</span> <span class="token builtin">cap</span><span class="token punctuation">.</span>Window<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        tm<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Warn</span><span class="token punctuation">(</span><span class="token string">"frequency_limit_check_error"</span><span class="token punctuation">,</span> <span class="token string">"error"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span> <span class="token comment">// 出错时允许通过</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> allowed</span>
<span class="line"><span class="token punctuation">}</span></span>
