<span class="line"><span class="token comment">// getFirstTriggerTime 获取首次触发时间</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>tm <span class="token operator">*</span>TriggerMatcher<span class="token punctuation">)</span> <span class="token function">getFirstTriggerTime</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> playerID <span class="token builtin">string</span><span class="token punctuation">,</span> campaignStart time<span class="token punctuation">.</span>Time<span class="token punctuation">)</span> <span class="token punctuation">(</span>time<span class="token punctuation">.</span>Time<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
