<span class="line">    player<span class="token punctuation">,</span> err <span class="token operator">:=</span> tm<span class="token punctuation">.</span>playerSvc<span class="token punctuation">.</span><span class="token function">GetPlayer</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> playerID<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
