<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>PlayerSnapshot<span class="token punctuation">{</span></span>
<span class="line">        PlayerID<span class="token punctuation">:</span>       player<span class="token punctuation">.</span>PlayerID<span class="token punctuation">,</span></span>
