<span class="line">                results<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">,</span> results<span class="token punctuation">[</span>j<span class="token punctuation">]</span> <span class="token operator">=</span> results<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">,</span> results<span class="token punctuation">[</span>i<span class="token punctuation">]</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
