e-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-3-频率限制器实现" tabindex="-1"><a class="header-anchor" href="#_1-3-频率限制器实现"><span>1.3 频率限制器实现</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/frequency_limiter.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"fmt"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/redis/go-redis/v9"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// RedisFrequencyLimiter 基于 Redis 的频率限制器</span></span>
<span class="line"><span class="token keyword">type</span> RedisFrequencyLimiter <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    client <span class="token operator">*</span>redis<span class="token punctuation">.</span>Client</span>
<span class="line">    prefix <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// NewRedisFrequencyLimiter 创建频率限制器</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewRedisFrequencyLimiter</span><span class="token punctuation">(</span>client <span class="token operator">*</span>redis<span class="token punctuation">.</span>Client<span class="token punctuation">)</span> <span class="token operator">*</span>RedisFrequencyLimiter <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>RedisFrequencyLimiter<span class="token punctuation">{</span></span>
<span class="line">        client<span class="token punctuation">:</span> client<span class="token punctuation">,</span></span>
<span class="line">        prefix<span class="token punctuation">:</span> <span class="token string">"campaign:freq"</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Check 检查是否允许</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>fl <span class="token operator">*</span>RedisFrequencyLimiter<span class="token punctuation">)</span> <span class="token function">Check</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> scope<span class="token punctuation">,</span> key <span class="token builtin">string</span><span class="token punctuation">,</span> limit <span class="token builtin">int</span><span class="token punctuation">,</span> window <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    redisKey <span class="token operator">:=</span> fl<span class="token punctuation">.</span><span class="token function">buildKey</span><span class="token punctuation">(</span>scope<span class="token punctuation">,</span> key<span class="token punctuation">,</span> window<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">switch</span> window <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"once"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 只检查是否存在</span></span>
<span class="line">        exists<span class="token punctuation">,</span> err <span class="token operator">:=</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Exists</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Result</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> exists <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">,</span> err</span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"daily"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 检查当天的计数</span></span>
<span class="line">        count<span class="token punctuation">,</span> err <span class="token operator">:=</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Int</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">==</span> redis<span class="token punctuation">.</span>Nil <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> count <span class="token operator">&lt;</span> limit<span class="token punctuation">,</span> err</span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"weekly"</span><span class="token punctuation">,</span> <span class="token string">"monthly"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 检查计数</span></span>
<span class="line">        count<span class="token punctuation">,</span> err <span class="token operator">:=</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Int</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">==</span> redis<span class="token punctuation">.</span>Nil <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> count <span class="token operator">&lt;</span> limit<span class="token punctuation">,</span> err</span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"activity"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 活动期间只触发一次</span></span>
<span class="line">        exists<span class="token punctuation">,</span> err <span class="token operator">:=</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Exists</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Result</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> exists <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">,</span> err</span>
<span class="line"></span>
<span class="line">    <span class="token keyword">default</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 自定义时间窗口，格式: "seconds:N"</span></span>
<span class="line">        <span class="token keyword">var</span> seconds <span class="token builtin">int</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Sscanf</span><span class="token punctuation">(</span>window<span class="token punctuation">,</span> <span class="token string">"seconds:%d"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>seconds<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> seconds <span class="token operator">></span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">            count<span class="token punctuation">,</span> err <span class="token operator">:=</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Int</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">if</span> err <span class="token operator">==</span> redis<span class="token punctuation">.</span>Nil <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token keyword">return</span> count <span class="token operator">&lt;</span> limit<span class="token punctuation">,</span> err</span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Record 记录触发</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>fl <span class="token operator">*</span>RedisFrequencyLimiter<span class="token punctuation">)</span> <span class="token function">Record</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> scope<span class="token punctuation">,</span> key<span class="token punctuation">,</span> window <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">    redisKey <span class="token operator">:=</span> fl<span class="token punctuation">.</span><span class="token function">buildKey</span><span class="token punctuation">(</span>scope<span class="token punctuation">,</span> key<span class="token punctuation">,</span> window<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">switch</span> window <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"once"</span><span class="token punctuation">,</span> <span class="token string">"activity"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 永久设置（或到活动结束）</span></span>
<span class="line">        <span class="token keyword">return</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Err</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"daily"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 设置过期时间为当天结束</span></span>
<span class="line">        now <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        endOfDay <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Date</span><span class="token punctuation">(</span>now<span class="token punctuation">.</span><span class="token function">Year</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> now<span class="token punctuation">.</span><span class="token function">Month</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> now<span class="token punctuation">.</span><span class="token function">Day</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">23</span><span class="token punctuation">,</span> <span class="token number">59</span><span class="token punctuation">,</span> <span class="token number">59</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> now<span class="token punctuation">.</span><span class="token function">Location</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        ttl <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Until</span><span class="token punctuation">(</span>endOfDay<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Incr</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Err</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token comment">// 需要同时设置过期时间（首次）</span></span>
<span class="line">        <span class="token comment">// TODO: 使用 Set NX 或 Lua 脚本</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"weekly"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 设置过期时间为本周结束</span></span>
<span class="line">        now <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        endOfWeek <span class="token operator">:=</span> now<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>time<span class="token punctuation">.</span><span class="token function">Duration</span><span class="token punctuation">(</span><span class="token number">7</span><span class="token operator">-</span><span class="token function">int</span><span class="token punctuation">(</span>now<span class="token punctuation">.</span><span class="token function">Weekday</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token number">24</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Hour<span class="token punctuation">)</span></span>
<span class="line">        ttl <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Until</span><span class="token punctuation">(</span>endOfWeek<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Incr</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Err</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"monthly"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 设置过期时间为本月结束</span></span>
<span class="line">        now <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        endOfMonth <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Date</span><span class="token punctuation">(</span>now<span class="token punctuation">.</span><span class="token function">Year</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> now<span class="token punctuation">.</span><span class="token function">Month</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">+</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> now<span class="token punctuation">.</span><span class="token function">Location</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span><span class="token operator">-</span>time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span></span>
<span class="line">        ttl <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Until</span><span class="token punctuation">(</span>endOfMonth<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Incr</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Err</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">default</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token comment">// 自定义时间窗口</span></span>
<span class="line">        <span class="token keyword">var</span> seconds <span class="token builtin">int</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Sscanf</span><span class="token punctuation">(</span>window<span class="token punctuation">,</span> <span class="token string">"seconds:%d"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>seconds<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> seconds <span class="token operator">></span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">            pipe <span class="token operator">:=</span> fl<span class="token punctuation">.</span>client<span class="token punctuation">.</span><span class="token function">Pipeline</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">            pipe<span class="token punctuation">.</span><span class="token function">Incr</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">)</span></span>
<span class="line">            pipe<span class="token punctuation">.</span><span class="token function">Expire</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> redisKey<span class="token punctuation">,</span> time<span class="token punctuation">.</span><span class="token function">Duration</span><span class="token punctuation">(</span>seconds<span class="token punctuation">)</span><span class="token operator">*</span>time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span></span>
<span class="line">            <span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> pipe<span class="token punctuation">.</span><span class="token function">Exec</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">return</span> err</span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// buildKey 构建 Redis 键</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>fl <span class="token operator">*</span>RedisFrequencyLimiter<span class="token punctuation">)</span> <span class="token function">buildKey</span><span class="token punctuation">(</span>scope<span class="token punctuation">,</span> key<span class="token punctuation">,</span> window <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">    dateSuffix <span class="token operator">:=</span> <span class="token string">""</span></span>
<span class="line">    <span class="token keyword">switch</span> window <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"daily"</span><span class="token punctuation">:</span></span>
<span class="line">        dateSuffix <span class="token operator">=</span> <span class="token string">":"</span> <span class="token operator">+</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Format</span><span class="token punctuation">(</span><span class="token string">"2006-01-02"</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"weekly"</span><span class="token punctuation">:</span></span>
<span class="line">        year<span class="token punctuation">,</span> week <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ISOWeek</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        dateSuffix <span class="token operator">=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">":%d-W%02d"</span><span class="token punctuation">,</span> year<span class="token punctuation">,</span> week<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"monthly"</span><span class="token punctuation">:</span></span>
<span class="line">        dateSuffix <span class="token operator">=</span> <span class="token string">":"</span> <span class="token operator">+</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Format</span><span class="token punctuation">(</span><span class="token string">"2006-01"</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"%s:%s:%s%s"</span><span class="token punctuation">,</span> fl<span class="token punctuation">.</span>prefix<span class="token punctuation">,</span> scope<span class="token punctuation">,</span> key<span class="token punctuation">,</span> dateSuffix<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
