<h2 id="_2-条件评估器-condition-evaluator" tabindex="-1"><a class="header-anchor" href="#_2-条件评估器-condition-evaluator"><span>2. 条件评估器 (Condition Evaluator)</span></a></h2>
<h3 id="_2-1-核心接口定义" tabindex="-1"><a class="header-anchor" href="#_2-1-核心接口定义"><span>2.1 核心接口定义</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/evaluator.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Evaluator 条件评估器接口</span></span>
<span class="line"><span class="token keyword">type</span> Evaluator <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Evaluate 评估条件组</span></span>
<span class="line">    <span class="token function">Evaluate</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> groups <span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>ConditionGroup<span class="token punctuation">,</span> input <span class="token operator">*</span>EvaluationInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// EvaluateGroup 评估单个条件组</span></span>
<span class="line">    <span class="token function">EvaluateGroup</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> group types<span class="token punctuation">.</span>ConditionGroup<span class="token punctuation">,</span> input <span class="token operator">*</span>EvaluationInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// EvaluationInput 评估输入</span></span>
<span class="line"><span class="token keyword">type</span> EvaluationInput <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Event     Event</span>
<span class="line">    Player    <span class="token operator">*</span>PlayerSnapshot</span>
<span class="line">    Progress  <span class="token operator">*</span>types<span class="token punctuation">.</span>PlayerProgress</span>
<span class="line">    Campaign  <span class="token operator">*</span>types<span class="token punctuation">.</span>CampaignInstance</span>
<span class="line">    Variables <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// EvaluationOutput 评估输出</span></span>
<span class="line"><span class="token keyword">type</span> EvaluationOutput <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Passed     <span class="token builtin">bool</span></span>
<span class="line">    Details    <span class="token punctuation">[</span><span class="token punctuation">]</span>ConditionDetail</span>
<span class="line">    Variables  <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token comment">// 可传递给后续使用</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ConditionDetail 条件评估详情</span></span>
<span class="line"><span class="token keyword">type</span> ConditionDetail <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    ConditionID <span class="token builtin">string</span></span>
<span class="line">    Type        <span class="token builtin">string</span></span>
<span class="line">    Passed      <span class="token builtin">bool</span></span>
<span class="line">    Reason      <span class="token builtin">string</span></span>
<span class="line">    Value       <span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span>    <span class="token comment">// 实际值</span></span>
<span class="line">    Expected    <span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span>    <span class="token comment">// 期望值</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-条件评估器实现" tabindex="-1"><a class="header-anchor" href="#_2-2-条件评估器实现"><span>2.2 条件评估器实现</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/condition_evaluator.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"fmt"</span></span>
<span class="line">    <span class="token string">"log/slog"</span></span>
<span class="line">    <span class="token string">"reflect"</span></span>
<span class="line">    <span class="token string">"strconv"</span></span>
<span class="line">    <span class="token string">"strings"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/Knetic/govaluate"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ConditionEvaluator 条件评估器</span></span>
<span class="line"><span class="token keyword">type</span> ConditionEvaluator <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    evaluators <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span>ConditionHandler</span>
<span class="line">    logger     <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ConditionHandler 条件处理器接口</span></span>
<span class="line"><span class="token keyword">type</span> ConditionHandler <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Evaluate 评估条件</span></span>
<span class="line">    <span class="token function">Evaluate</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> cond types<span class="token punctuation">.</span>Condition<span class="token punctuation">,</span> input <span class="token operator">*</span>EvaluationInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token operator">*</span>ConditionDetail<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Validate 验证条件配置</span></span>
<span class="line">    <span class="token function">Validate</span><span class="token punctuation">(</span>cond types<span class="token punctuation">.</span>Condition<span class="token punctuation">)</span> <span class="token builtin">error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// NewConditionEvaluator 创建条件评估器</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewConditionEvaluator</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span>ConditionEvaluator <span class="token punctuation">{</span></span>
<span class="line">    ce <span class="token operator">:=</span> <span class="token operator">&amp;</span>ConditionEvaluator<span class="token punctuation">{</span></span>
<span class="line">        evaluators<span class="token punctuation">:</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span>ConditionHandler<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        logger<span class="token punctuation">:</span>     slog<span class="token punctuation">.</span><span class="token function">Default</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 注册内置处理器</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"player_level"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>PlayerLevelHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"vip_level"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>VIPLevelHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"recharge_amount"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>RechargeAmountHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"recharge_count"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>RechargeCountHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"online_duration"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>OnlineDurationHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"register_days"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>RegisterDaysHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"activity_progress"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>ActivityProgressHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"event_count"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>EventCountHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    ce<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"expression"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>ExpressionHandler<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> ce</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// RegisterHandler 注册条件处理器</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ce <span class="token operator">*</span>ConditionEvaluator<span class="token punctuation">)</span> <span class="token function">RegisterHandler</span><span class="token punctuation">(</span>condType <span class="token builtin">string</span><span class="token punctuation">,</span> handler ConditionHandler<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    ce<span class="token punctuation">.</span>evaluators<span class="token punctuation">[</span>condType<span class="token punctuation">]</span> <span class="token operator">=</span> handler</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Evaluate 评估条件组</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ce <span class="token operator">*</span>ConditionEvaluator<span class="token punctuation">)</span> <span class="token function">Evaluate</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> groups <span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>ConditionGroup<span class="token punctuation">,</span> input <span class="token operator">*</span>EvaluationInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>groups<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span> <span class="token comment">// 无条件则通过</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 组之间是 OR 关系（任一组通过即可）</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> group <span class="token operator">:=</span> <span class="token keyword">range</span> groups <span class="token punctuation">{</span></span>
<span class="line">        passed<span class="token punctuation">,</span> err <span class="token operator">:=</span> ce<span class="token punctuation">.</span><span class="token function">EvaluateGroup</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> group<span class="token punctuation">,</span> input<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">            ce<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Warn</span><span class="token punctuation">(</span><span class="token string">"condition_group_error"</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"group_id"</span><span class="token punctuation">,</span> group<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"error"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">continue</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">if</span> passed <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// EvaluateGroup 评估单个条件组</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ce <span class="token operator">*</span>ConditionEvaluator<span class="token punctuation">)</span> <span class="token function">EvaluateGroup</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> group types<span class="token punctuation">.</span>ConditionGroup<span class="token punctuation">,</span> input <span class="token operator">*</span>EvaluationInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>group<span class="token punctuation">.</span>Conditions<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    passed <span class="token operator">:=</span> <span class="token boolean">true</span></span>
<span class="line">    details <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>ConditionDetail<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">len</span><span class="token punctuation">(</span>group<span class="token punctuation">.</span>Conditions<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> cond <span class="token operator">:=</span> <span class="token keyword">range</span> group<span class="token punctuation">.</span>Conditions <span class="token punctuation">{</span></span>
<span class="line">        handler<span class="token punctuation">,</span> ok <span class="token operator">:=</span> ce<span class="token punctuation">.</span>evaluators<span class="token punctuation">[</span>cond<span class="token punctuation">.</span>Type<span class="token punctuation">]</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token operator">!</span>ok <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"unknown condition type: %s"</span><span class="token punctuation">,</span> cond<span class="token punctuation">.</span>Type<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        condPassed<span class="token punctuation">,</span> detail<span class="token punctuation">,</span> err <span class="token operator">:=</span> handler<span class="token punctuation">.</span><span class="token function">Evaluate</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> cond<span class="token punctuation">,</span> input<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"evaluate condition %s: %w"</span><span class="token punctuation">,</span> cond<span class="token punctuation">.</span>ID<span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        details <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>details<span class="token punctuation">,</span> <span class="token operator">*</span>detail<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 根据 RequireAll 决定逻辑</span></span>
<span class="line">        <span class="token keyword">if</span> group<span class="token punctuation">.</span>RequireAll <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// AND: 任一失败则整体失败</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token operator">!</span>condPassed <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// OR: 任一成功则整体成功</span></span>
<span class="line">            <span class="token keyword">if</span> condPassed <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            passed <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// AND 全部通过 / OR 全部失败</span></span>
<span class="line">    <span class="token keyword">return</span> passed<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
