iv><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-内置条件处理器" tabindex="-1"><a class="header-anchor" href="#_2-3-内置条件处理器"><span>2.3 内置条件处理器</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/conditions/player_level.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> conditions</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"fmt"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/engine"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// PlayerLevelHandler 玩家等级条件处理器</span></span>
<span class="line"><span class="token keyword">type</span> PlayerLevelHandler <span class="token keyword">struct</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>PlayerLevelHandler<span class="token punctuation">)</span> <span class="token function">Evaluate</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> cond types<span class="token punctuation">.</span>Condition<span class="token punctuation">,</span> input <span class="token operator">*</span>engine<span class="token punctuation">.</span>EvaluationInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">bool</span><span class="token punctuation">,</span> <span class="token operator">*</span>engine<span class="token punctuation">.</span>ConditionDetail<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> input<span class="token punctuation">.</span>Player <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>engine<span class="token punctuation">.</span>ConditionDetail<span class="token punctuation">{</span></span>
<span class="line">            ConditionID<span class="token punctuation">:</span> cond<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">            Type<span class="token punctuation">:</span>        cond<span class="token punctuation">.</span>Type<span class="token punctuation">,</span></span>
<span class="line">            Passed<span class="token punctuation">:</span>      <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">            Reason<span class="token punctuation">:</span>      <span class="token string">"player not found"</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    actualLevel <span class="token operator">:=</span> <span class="token function">int</span><span class="token punctuation">(</span>input<span class="token punctuation">.</span>Player<span class="token punctuation">.</span>Level<span class="token punctuation">)</span></span>
<span class="line">    expectedLevel <span class="token operator">:=</span> <span class="token function">parseInt</span><span class="token punctuation">(</span>cond<span class="token punctuation">.</span>Value<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    passed <span class="token operator">:=</span> <span class="token function">compareNumbers</span><span class="token punctuation">(</span>actualLevel<span class="token punctuation">,</span> cond<span class="token punctuation">.</span>Operator<span class="token punctuation">,</span> expectedLevel<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> passed<span class="token punctuation">,</span> <span class="token operator">&amp;</span>engine<span class="token punctuation">.</span>ConditionDetail<span class="token punctuation">{</span></span>
<span class="line">        ConditionID<span class="token punctuation">:</span> cond<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">        Type<span class="token punctuation">:</span>        cond<span class="token punctuation">.</span>Type<span class="token punctuation">,</span></span>
<span class="line">        Passed<span class="token punctuation">:</span>      passed<span class="token punctuation">,</span></span>
<span class="line">        Reason<span class="token punctuation">:</span>      fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"player level %d %s %d"</span><span class="token punctuation">,</span> actualLevel<span class="token punctuation">,</span> cond<span class="token punctuation">.</span>Operator<span class="token punctuation">,</span> expectedLevel<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        Value<span class="token punctuation">:</span>       actualLevel<span class="token punctuation">,</span></span>
<span class="line">        Expected<span class="token punctuation">:</span>    expectedLevel<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
