<span class="line">    <span class="token comment">// 创建表达式</span></span>
<span class="line">    expr<span class="token punctuation">,</span> err <span class="token operator">:=</span> govaluate<span class="token punctuation">.</span><span class="token function">NewEvaluableExpression</span><span class="token punctuation">(</span>exprStr<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"parse expression: %w"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
