<span class="line"></span>
<span class="line"><span class="token comment">// buildParameters 构建表达式参数</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>ExpressionHandler<span class="token punctuation">)</span> <span class="token function">buildParameters</span><span class="token punctuation">(</span>input <span class="token operator">*</span>engine<span class="token punctuation">.</span>EvaluationInput<span class="token punctuation">)</span> <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">{</span></span>
<span class="line">    params <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 玩家属性</span></span>
<span class="line">    <span class="token keyword">if</span> input<span class="token punctuation">.</span>Player <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        params<span class="token punctuation">[</span><span class="token string">"player_level"</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">int</span><span class="token punctuation">(</span>input<span class="token punctuation">.</span>Player<span class="token punctuation">.</span>Level<span class="token punctuation">)</span></span>
<span class="line">        params<span class="token punctuation">[</span><span class="token string">"vip_level"</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">int</span><span class="token punctuation">(</span>input<span class="token punctuation">.</span>Player<span class="token punctuation">.</span>VIPLevel<span class="token punctuation">)</span></span>
<span class="line">        params<span class="token punctuation">[</span><span class="token string">"total_recharge"</span><span class="token punctuation">]</span> <span class="token operator">=</span> input<span class="token punctuation">.</span>Player<span class="token punctuation">.</span>TotalRecharge</span>
<span class="line">        params<span class="token punctuation">[</span><span class="token string">"player_id"</span><span class="token punctuation">]</span> <span class="token operator">=</span> input<span class="token punctuation">.</span>Player<span class="token punctuation">.</span>PlayerID</span>
