<span class="line"></span>
<span class="line">    <span class="token comment">// 活动进度</span></span>
<span class="line">    <span class="token keyword">if</span> input<span class="token punctuation">.</span>Progress <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        params<span class="token punctuation">[</span><span class="token string">"stage"</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">int</span><span class="token punctuation">(</span>input<span class="token punctuation">.</span>Progress<span class="token punctuation">.</span>Stage<span class="token punctuation">)</span></span>
<span class="line">        params<span class="token punctuation">[</span><span class="token string">"trigger_count"</span><span class="token punctuation">]</span> <span class="token operator">=</span> input<span class="token punctuation">.</span>Progress<span class="token punctuation">.</span>TriggerCount</span>
