<span class="line">    <span class="token keyword">for</span> k<span class="token punctuation">,</span> v <span class="token operator">:=</span> <span class="token keyword">range</span> input<span class="token punctuation">.</span>Event<span class="token punctuation">.</span>Properties <span class="token punctuation">{</span></span>
<span class="line">        key <span class="token operator">:=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"event_%s"</span><span class="token punctuation">,</span> <span class="token function">toSnakeCase</span><span class="token punctuation">(</span>k<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        params<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">=</span> v</span>
