<span class="line"></span>
<span class="line">    <span class="token comment">// 上下文变量</span></span>
<span class="line">    <span class="token keyword">for</span> k<span class="token punctuation">,</span> v <span class="token operator">:=</span> <span class="token keyword">range</span> input<span class="token punctuation">.</span>Variables <span class="token punctuation">{</span></span>
