<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/conditions/utils.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> conditions</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"reflect"</span></span>
<span class="line">    <span class="token string">"strconv"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// compareNumbers 比较数字</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">compareNumbers</span><span class="token punctuation">(</span>a <span class="token builtin">int</span><span class="token punctuation">,</span> operator <span class="token builtin">string</span><span class="token punctuation">,</span> b <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">switch</span> operator <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">">"</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> a <span class="token operator">></span> b</span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">">="</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> a <span class="token operator">>=</span> b</span>
<span class="line">    <span class="token keyword">case</span> <span class="token string">"=="</span><span class="token punctuation">:</span></span>
