<h2 id="_3-动作执行器-action-executor" tabindex="-1"><a class="header-anchor" href="#_3-动作执行器-action-executor"><span>3. 动作执行器 (Action Executor)</span></a></h2>
<h3 id="_3-1-核心接口定义" tabindex="-1"><a class="header-anchor" href="#_3-1-核心接口定义"><span>3.1 核心接口定义</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/executor.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Executor 动作执行器接口</span></span>
<span class="line"><span class="token keyword">type</span> Executor <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Execute 执行动作列表</span></span>
<span class="line">    <span class="token function">Execute</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> actions <span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> input <span class="token operator">*</span>ExecutionInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>ExecutionOutput<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// ExecuteAction 执行单个动作</span></span>
<span class="line">    <span class="token function">ExecuteAction</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> action types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> input <span class="token operator">*</span>ExecutionInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>ActionResult<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ExecutionInput 执行输入</span></span>
<span class="line"><span class="token keyword">type</span> ExecutionInput <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Event       Event</span>
<span class="line">    Campaign    <span class="token operator">*</span>types<span class="token punctuation">.</span>CampaignInstance</span>
<span class="line">    PlayerID    <span class="token builtin">string</span></span>
<span class="line">    Player      <span class="token operator">*</span>PlayerSnapshot</span>
<span class="line">    Progress    <span class="token operator">*</span>types<span class="token punctuation">.</span>PlayerProgress</span>
<span class="line">    MatchResult <span class="token operator">*</span>MatchResult</span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 上下文数据（可在动作间传递）</span></span>
<span class="line">    ContextData <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ExecutionOutput 执行输出</span></span>
<span class="line"><span class="token keyword">type</span> ExecutionOutput <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Success     <span class="token builtin">bool</span></span>
<span class="line">    Results     <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">*</span>ActionResult</span>
<span class="line">    Error       <span class="token builtin">error</span></span>
<span class="line">    DurationMs  <span class="token builtin">int64</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 更新的数据</span></span>
<span class="line">    UpdatedProgress <span class="token operator">*</span>types<span class="token punctuation">.</span>PlayerProgress</span>
<span class="line">    ContextData     <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ActionResult 单个动作执行结果</span></span>
<span class="line"><span class="token keyword">type</span> ActionResult <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    ActionID    <span class="token builtin">string</span></span>
<span class="line">    ActionType  <span class="token builtin">string</span></span>
<span class="line">    Success     <span class="token builtin">bool</span></span>
<span class="line">    Error       <span class="token builtin">error</span></span>
<span class="line">    Result      <span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line">    DurationMs  <span class="token builtin">int64</span></span>
<span class="line">    RetryCount  <span class="token builtin">int</span></span>
<span class="line">    Skipped     <span class="token builtin">bool</span></span>
<span class="line">    SkipReason  <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-动作执行器实现" tabindex="-1"><a class="header-anchor" href="#_3-2-动作执行器实现"><span>3.2 动作执行器实现</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/action_executor.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"fmt"</span></span>
<span class="line">    <span class="token string">"log/slog"</span></span>
<span class="line">    <span class="token string">"sync"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ActionExecutor 动作执行器</span></span>
<span class="line"><span class="token keyword">type</span> ActionExecutor <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    handlers   <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span>ActionHandler</span>
<span class="line">    repository ProgressRepository</span>
<span class="line">    logger     <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger</span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 配置</span></span>
<span class="line">    maxConcurrent <span class="token builtin">int</span></span>
<span class="line">    defaultRetry  <span class="token operator">*</span>RetryConfig</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ActionHandler 动作处理器接口</span></span>
<span class="line"><span class="token keyword">type</span> ActionHandler <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Execute 执行动作</span></span>
<span class="line">    <span class="token function">Execute</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> action types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> input <span class="token operator">*</span>ExecutionInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Validate 验证动作配置</span></span>
<span class="line">    <span class="token function">Validate</span><span class="token punctuation">(</span>action types<span class="token punctuation">.</span>Action<span class="token punctuation">)</span> <span class="token builtin">error</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// ShouldRetry 判断是否应该重试</span></span>
<span class="line">    <span class="token function">ShouldRetry</span><span class="token punctuation">(</span>err <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token builtin">bool</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// RetryConfig 重试配置</span></span>
<span class="line"><span class="token keyword">type</span> RetryConfig <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    MaxRetries  <span class="token builtin">int</span></span>
<span class="line">    IntervalMs  <span class="token builtin">int</span></span>
<span class="line">    BackoffRate <span class="token builtin">float64</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// NewActionExecutor 创建动作执行器</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewActionExecutor</span><span class="token punctuation">(</span>repo ProgressRepository<span class="token punctuation">)</span> <span class="token operator">*</span>ActionExecutor <span class="token punctuation">{</span></span>
<span class="line">    ae <span class="token operator">:=</span> <span class="token operator">&amp;</span>ActionExecutor<span class="token punctuation">{</span></span>
<span class="line">        handlers<span class="token punctuation">:</span>      <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span>ActionHandler<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        repository<span class="token punctuation">:</span>    repo<span class="token punctuation">,</span></span>
<span class="line">        logger<span class="token punctuation">:</span>        slog<span class="token punctuation">.</span><span class="token function">Default</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        maxConcurrent<span class="token punctuation">:</span> <span class="token number">50</span><span class="token punctuation">,</span></span>
