<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> results</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// executeActionWithRetry 带重试的执行</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ae <span class="token operator">*</span>ActionExecutor<span class="token punctuation">)</span> <span class="token function">executeActionWithRetry</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> action types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> input <span class="token operator">*</span>ExecutionInput<span class="token punctuation">)</span> <span class="token operator">*</span>ActionResult <span class="token punctuation">{</span></span>
<span class="line">    startTime <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    result <span class="token operator">:=</span> <span class="token operator">&amp;</span>ActionResult<span class="token punctuation">{</span></span>
<span class="line">        ActionID<span class="token punctuation">:</span>   action<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">        ActionType<span class="token punctuation">:</span> action<span class="token punctuation">.</span>Type<span class="token punctuation">,</span></span>
<span class="line">        Success<span class="token punctuation">:</span>    <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 获取重试配置</span></span>
<span class="line">    retryConfig <span class="token operator">:=</span> ae<span class="token punctuation">.</span>defaultRetry</span>
<span class="line">    <span class="token keyword">if</span> action<span class="token punctuation">.</span>RetryConfig <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        retryConfig <span class="token operator">=</span> <span class="token operator">&amp;</span>RetryConfig<span class="token punctuation">{</span></span>
<span class="line">            MaxRetries<span class="token punctuation">:</span>  action<span class="token punctuation">.</span>RetryConfig<span class="token punctuation">.</span>MaxRetries<span class="token punctuation">,</span></span>
<span class="line">            IntervalMs<span class="token punctuation">:</span>  action<span class="token punctuation">.</span>RetryConfig<span class="token punctuation">.</span>IntervalMs<span class="token punctuation">,</span></span>
<span class="line">            BackoffRate<span class="token punctuation">:</span> action<span class="token punctuation">.</span>RetryConfig<span class="token punctuation">.</span>BackoffRate<span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    handler<span class="token punctuation">,</span> ok <span class="token operator">:=</span> ae<span class="token punctuation">.</span>handlers<span class="token punctuation">[</span>action<span class="token punctuation">.</span>Type<span class="token punctuation">]</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>ok <span class="token punctuation">{</span></span>
<span class="line">        result<span class="token punctuation">.</span>Error <span class="token operator">=</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"unknown action type: %s"</span><span class="token punctuation">,</span> action<span class="token punctuation">.</span>Type<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> result</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 执行（带重试）</span></span>
<span class="line">    <span class="token keyword">var</span> lastErr <span class="token builtin">error</span></span>
<span class="line">    <span class="token keyword">for</span> attempt <span class="token operator">:=</span> <span class="token number">0</span><span class="token punctuation">;</span> attempt <span class="token operator">&lt;=</span> retryConfig<span class="token punctuation">.</span>MaxRetries<span class="token punctuation">;</span> attempt<span class="token operator">++</span> <span class="token punctuation">{</span></span>
<span class="line">        result<span class="token punctuation">.</span>RetryCount <span class="token operator">=</span> attempt</span>
<span class="line"></span>
<span class="line">        output<span class="token punctuation">,</span> err <span class="token operator">:=</span> handler<span class="token punctuation">.</span><span class="token function">Execute</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> action<span class="token punctuation">,</span> input<span class="token punctuation">)</span></span>
<span class="line">        lastErr <span class="token operator">=</span> err</span>
<span class="line"></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">            result<span class="token punctuation">.</span>Success <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">            result<span class="token punctuation">.</span>Result <span class="token operator">=</span> output</span>
<span class="line">            result<span class="token punctuation">.</span>DurationMs <span class="token operator">=</span> time<span class="token punctuation">.</span><span class="token function">Since</span><span class="token punctuation">(</span>startTime<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Milliseconds</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">            ae<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Debug</span><span class="token punctuation">(</span><span class="token string">"action_success"</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"action_id"</span><span class="token punctuation">,</span> action<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"action_type"</span><span class="token punctuation">,</span> action<span class="token punctuation">.</span>Type<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"duration_ms"</span><span class="token punctuation">,</span> result<span class="token punctuation">.</span>DurationMs<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"attempt"</span><span class="token punctuation">,</span> attempt<span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">return</span> result</span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 检查是否应该重试</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token operator">!</span>handler<span class="token punctuation">.</span><span class="token function">ShouldRetry</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">break</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">if</span> attempt <span class="token operator">&lt;</span> retryConfig<span class="token punctuation">.</span>MaxRetries <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 计算退避时间</span></span>
<span class="line">            sleepMs <span class="token operator">:=</span> <span class="token function">int</span><span class="token punctuation">(</span><span class="token function">float64</span><span class="token punctuation">(</span>retryConfig<span class="token punctuation">.</span>IntervalMs<span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token function">pow</span><span class="token punctuation">(</span>retryConfig<span class="token punctuation">.</span>BackoffRate<span class="token punctuation">,</span> <span class="token function">float64</span><span class="token punctuation">(</span>attempt<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">            ae<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Debug</span><span class="token punctuation">(</span><span class="token string">"action_retry"</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"action_id"</span><span class="token punctuation">,</span> action<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"attempt"</span><span class="token punctuation">,</span> attempt<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"next_retry_ms"</span><span class="token punctuation">,</span> sleepMs<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"error"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">            <span class="token keyword">select</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">case</span> <span class="token operator">&lt;-</span>time<span class="token punctuation">.</span><span class="token function">After</span><span class="token punctuation">(</span>time<span class="token punctuation">.</span><span class="token function">Duration</span><span class="token punctuation">(</span>sleepMs<span class="token punctuation">)</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Millisecond<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">            <span class="token keyword">case</span> <span class="token operator">&lt;-</span>ctx<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">                result<span class="token punctuation">.</span>Error <span class="token operator">=</span> ctx<span class="token punctuation">.</span><span class="token function">Err</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">                <span class="token keyword">return</span> result</span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    result<span class="token punctuation">.</span>Error <span class="token operator">=</span> lastErr</span>
<span class="line">    result<span class="token punctuation">.</span>DurationMs <span class="token operator">=</span> time<span class="token punctuation">.</span><span class="token function">Since</span><span class="token punctuation">(</span>startTime<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Milliseconds</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    ae<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Warn</span><span class="token punctuation">(</span><span class="token string">"action_failed_after_retries"</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"action_id"</span><span class="token punctuation">,</span> action<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"attempts"</span><span class="token punctuation">,</span> result<span class="token punctuation">.</span>RetryCount<span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"error"</span><span class="token punctuation">,</span> lastErr<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> result</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// shouldSkipAction 检查是否应该跳过动作</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ae <span class="token operator">*</span>ActionExecutor<span class="token punctuation">)</span> <span class="token function">shouldSkipAction</span><span class="token punctuation">(</span>action types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> input <span class="token operator">*</span>ExecutionInput<span class="token punctuation">)</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> action<span class="token punctuation">.</span>Dependency <span class="token operator">==</span> <span class="token string">""</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token string">""</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 检查依赖的前置动作结果</span></span>
<span class="line">    <span class="token comment">// TODO: 从上下文中获取前置动作结果</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token string">""</span></span>
<span class="line"><span class="token punctuation">}</span></span>
