<span class="line"><span class="token comment">// updateContextData 更新上下文数据</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ae <span class="token operator">*</span>ActionExecutor<span class="token punctuation">)</span> <span class="token function">updateContextData</span><span class="token punctuation">(</span>input <span class="token operator">*</span>ExecutionInput<span class="token punctuation">,</span> action types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> result <span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> input<span class="token punctuation">.</span>ContextData <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        input<span class="token punctuation">.</span>ContextData <span class="token operator">=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    input<span class="token punctuation">.</span>ContextData<span class="token punctuation">[</span><span class="token string">"action_"</span><span class="token operator">+</span>action<span class="token punctuation">.</span>ID<span class="token operator">+</span><span class="token string">"_result"</span><span class="token punctuation">]</span> <span class="token operator">=</span> result</span>
