<span class="line"><span class="token comment">// allActionsSuccess 检查所有动作是否成功</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ae <span class="token operator">*</span>ActionExecutor<span class="token punctuation">)</span> <span class="token function">allActionsSuccess</span><span class="token punctuation">(</span>results <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">*</span>ActionResult<span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> r <span class="token operator">:=</span> <span class="token keyword">range</span> results <span class="token punctuation">{</span></span>
