<span class="line"><span class="token comment">// pow 计算幂</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">pow</span><span class="token punctuation">(</span>base<span class="token punctuation">,</span> exp <span class="token builtin">float64</span><span class="token punctuation">)</span> <span class="token builtin">float64</span> <span class="token punctuation">{</span></span>
