v><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-动作-dag-实现" tabindex="-1"><a class="header-anchor" href="#_3-3-动作-dag-实现"><span>3.3 动作 DAG 实现</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/action_dag.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"fmt"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ActionDAG 动作依赖图</span></span>
<span class="line"><span class="token keyword">type</span> ActionDAG <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Actions <span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>Action</span>
<span class="line">    Layers  <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>Action <span class="token comment">// 按依赖关系分层的动作</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// buildActionDAG 构建动作 DAG</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>ae <span class="token operator">*</span>ActionExecutor<span class="token punctuation">)</span> <span class="token function">buildActionDAG</span><span class="token punctuation">(</span>actions <span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>Action<span class="token punctuation">)</span> <span class="token operator">*</span>ActionDAG <span class="token punctuation">{</span></span>
<span class="line">    dag <span class="token operator">:=</span> <span class="token operator">&amp;</span>ActionDAG<span class="token punctuation">{</span></span>
<span class="line">        Actions<span class="token punctuation">:</span> actions<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>actions<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> dag</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 构建依赖图</span></span>
<span class="line">    actionMap <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token operator">*</span>types<span class="token punctuation">.</span>Action<span class="token punctuation">)</span></span>
<span class="line">    inDegree <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token builtin">int</span><span class="token punctuation">)</span></span>
<span class="line">    dependents <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> i <span class="token operator">:=</span> <span class="token keyword">range</span> actions <span class="token punctuation">{</span></span>
<span class="line">        actionMap<span class="token punctuation">[</span>actions<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">.</span>ID<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token operator">&amp;</span>actions<span class="token punctuation">[</span>i<span class="token punctuation">]</span></span>
<span class="line">        inDegree<span class="token punctuation">[</span>actions<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">.</span>ID<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> action <span class="token operator">:=</span> <span class="token keyword">range</span> actions <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> action<span class="token punctuation">.</span>Dependency <span class="token operator">!=</span> <span class="token string">""</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token boolean">_</span><span class="token punctuation">,</span> exists <span class="token operator">:=</span> actionMap<span class="token punctuation">[</span>action<span class="token punctuation">.</span>Dependency<span class="token punctuation">]</span><span class="token punctuation">;</span> exists <span class="token punctuation">{</span></span>
<span class="line">                inDegree<span class="token punctuation">[</span>action<span class="token punctuation">.</span>ID<span class="token punctuation">]</span><span class="token operator">++</span></span>
<span class="line">                dependents<span class="token punctuation">[</span>action<span class="token punctuation">.</span>Dependency<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>dependents<span class="token punctuation">[</span>action<span class="token punctuation">.</span>Dependency<span class="token punctuation">]</span><span class="token punctuation">,</span> action<span class="token punctuation">.</span>ID<span class="token punctuation">)</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 拓扑排序，分层执行</span></span>
<span class="line">    queue <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">for</span> actionID<span class="token punctuation">,</span> degree <span class="token operator">:=</span> <span class="token keyword">range</span> inDegree <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> degree <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">            queue <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>queue<span class="token punctuation">,</span> actionID<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    layers <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token function">len</span><span class="token punctuation">(</span>queue<span class="token punctuation">)</span> <span class="token operator">></span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        layerSize <span class="token operator">:=</span> <span class="token function">len</span><span class="token punctuation">(</span>queue<span class="token punctuation">)</span></span>
<span class="line">        layer <span class="token operator">:=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> layerSize<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">for</span> i <span class="token operator">:=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> layerSize<span class="token punctuation">;</span> i<span class="token operator">++</span> <span class="token punctuation">{</span></span>
<span class="line">            actionID <span class="token operator">:=</span> queue<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span></span>
<span class="line">            queue <span class="token operator">=</span> queue<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">:</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">            action <span class="token operator">:=</span> <span class="token operator">*</span>actionMap<span class="token punctuation">[</span>actionID<span class="token punctuation">]</span></span>
<span class="line">            layer <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>layer<span class="token punctuation">,</span> action<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">            <span class="token comment">// 处理依赖此动作的其他动作</span></span>
<span class="line">            <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> dependentID <span class="token operator">:=</span> <span class="token keyword">range</span> dependents<span class="token punctuation">[</span>actionID<span class="token punctuation">]</span> <span class="token punctuation">{</span></span>
<span class="line">                inDegree<span class="token punctuation">[</span>dependentID<span class="token punctuation">]</span><span class="token operator">--</span></span>
<span class="line">                <span class="token keyword">if</span> inDegree<span class="token punctuation">[</span>dependentID<span class="token punctuation">]</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">                    queue <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>queue<span class="token punctuation">,</span> dependentID<span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        layers <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>layers<span class="token punctuation">,</span> layer<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    dag<span class="token punctuation">.</span>Layers <span class="token operator">=</span> layers</span>
<span class="line">    <span class="token keyword">return</span> dag</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
