iv><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-内置动作处理器" tabindex="-1"><a class="header-anchor" href="#_3-4-内置动作处理器"><span>3.4 内置动作处理器</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/actions/grant_reward.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> actions</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"encoding/json"</span></span>
<span class="line">    <span class="token string">"fmt"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/engine"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/service/gamesvc"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// GrantRewardHandler 奖励发放处理器</span></span>
<span class="line"><span class="token keyword">type</span> GrantRewardHandler <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    gameClient gamesvc<span class="token punctuation">.</span>GameServiceClient</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> GrantRewardParams <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Rewards <span class="token punctuation">[</span><span class="token punctuation">]</span>RewardItem <span class="token string">`json:"rewards"`</span></span>
<span class="line">    Mail    <span class="token operator">*</span>MailInfo    <span class="token string">`json:"mail,omitempty"`</span></span>
<span class="line">    Notify  <span class="token builtin">bool</span>         <span class="token string">`json:"notify"`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> RewardItem <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Type    <span class="token builtin">string</span> <span class="token string">`json:"type"`</span>    <span class="token comment">// item/currency/title/exp/honor</span></span>
<span class="line">    ID      <span class="token builtin">string</span> <span class="token string">`json:"id"`</span>      <span class="token comment">// 物品ID / 货币类型</span></span>
<span class="line">    Count   <span class="token builtin">int64</span>  <span class="token string">`json:"count"`</span>   <span class="token comment">// 数量</span></span>
<span class="line">    Quality <span class="token builtin">string</span> <span class="token string">`json:"quality"`</span> <span class="token comment">// 品质: common/rare/epic/legendary</span></span>
<span class="line">    Bind    <span class="token builtin">bool</span>   <span class="token string">`json:"bind"`</span>    <span class="token comment">// 是否绑定</span></span>
<span class="line">    Expire  <span class="token builtin">int32</span>  <span class="token string">`json:"expire"`</span>  <span class="token comment">// 过期时间（天），0表示永久</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> MailInfo <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Title       <span class="token builtin">string</span> <span class="token string">`json:"title"`</span></span>
<span class="line">    Content     <span class="token builtin">string</span> <span class="token string">`json:"content"`</span></span>
<span class="line">    Sender      <span class="token builtin">string</span> <span class="token string">`json:"sender"`</span></span>
<span class="line">    ExpireDays  <span class="token builtin">int32</span>  <span class="token string">`json:"expire_days"`</span></span>
<span class="line">    Attachments <span class="token punctuation">[</span><span class="token punctuation">]</span>RewardItem <span class="token string">`json:"attachments"`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>GrantRewardHandler<span class="token punctuation">)</span> <span class="token function">Execute</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> action types<span class="token punctuation">.</span>Action<span class="token punctuation">,</span> input <span class="token operator">*</span>engine<span class="token punctuation">.</span>ExecutionInput<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">var</span> params GrantRewardParams</span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>action<span class="token punctuation">.</span>Params<span class="token punctuation">,</span> <span class="token operator">&amp;</span>params<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"parse params: %w"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 构建请求</span></span>
<span class="line">    request <span class="token operator">:=</span> <span class="token operator">&amp;</span>gamesvc<span class="token punctuation">.</span>GrantRewardRequest<span class="token punctuation">{</span></span>
<span class="line">        PlayerID<span class="token punctuation">:</span>   input<span class="token punctuation">.</span>PlayerID<span class="token punctuation">,</span></span>
<span class="line">        CampaignID<span class="token punctuation">:</span> input<span class="token punctuation">.</span>Campaign<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">        ActionID<span class="token punctuation">:</span>   action<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">        Rewards<span class="token punctuation">:</span>    <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>gamesvc<span class="token punctuation">.</span>RewardItem<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">len</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>Rewards<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 转换奖励项</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> r <span class="token operator">:=</span> <span class="token keyword">range</span> params<span class="token punctuation">.</span>Rewards <span class="token punctuation">{</span></span>
<span class="line">        request<span class="token punctuation">.</span>Rewards <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>request<span class="token punctuation">.</span>Rewards<span class="token punctuation">,</span> gamesvc<span class="token punctuation">.</span>RewardItem<span class="token punctuation">{</span></span>
<span class="line">            Type<span class="token punctuation">:</span>    r<span class="token punctuation">.</span>Type<span class="token punctuation">,</span></span>
<span class="line">            ID<span class="token punctuation">:</span>      r<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">            Count<span class="token punctuation">:</span>   r<span class="token punctuation">.</span>Count<span class="token punctuation">,</span></span>
<span class="line">            Quality<span class="token punctuation">:</span> r<span class="token punctuation">.</span>Quality<span class="token punctuation">,</span></span>
<span class="line">            Bind<span class="token punctuation">:</span>    r<span class="token punctuation">.</span>Bind<span class="token punctuation">,</span></span>
<span class="line">            Expire<span class="token punctuation">:</span>  r<span class="token punctuation">.</span>Expire<span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 如果配置了邮件，通过邮件发送</span></span>
<span class="line">    <span class="token keyword">if</span> params<span class="token punctuation">.</span>Mail <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        request<span class="token punctuation">.</span>MailTitle <span class="token operator">=</span> params<span class="token punctuation">.</span>Mail<span class="token punctuation">.</span>Title</span>
<span class="line">        request<span class="token punctuation">.</span>MailContent <span class="token operator">=</span> params<span class="token punctuation">.</span>Mail<span class="token punctuation">.</span>Content</span>
<span class="line">        request<span class="token punctuation">.</span>MailSender <span class="token operator">=</span> params<span class="token punctuation">.</span>Mail<span class="token punctuation">.</span>Sender</span>
<span class="line">        request<span class="token punctuation">.</span>MailExpireDays <span class="token operator">=</span> params<span class="token punctuation">.</span>Mail<span class="token punctuation">.</span>ExpireDays</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 调用游戏服务</span></span>
<span class="line">    response<span class="token punctuation">,</span> err <span class="token operator">:=</span> h<span class="token punctuation">.</span>gameClient<span class="token punctuation">.</span><span class="token function">GrantReward</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> request<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"grant reward: %w"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 返回结果</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>GrantRewardResult<span class="token punctuation">{</span></span>
<span class="line">        Success<span class="token punctuation">:</span>     response<span class="token punctuation">.</span>Success<span class="token punctuation">,</span></span>
<span class="line">        Granted<span class="token punctuation">:</span>     response<span class="token punctuation">.</span>GrantedItems<span class="token punctuation">,</span></span>
<span class="line">        MailID<span class="token punctuation">:</span>      response<span class="token punctuation">.</span>MailID<span class="token punctuation">,</span></span>
<span class="line">        Balance<span class="token punctuation">:</span>     response<span class="token punctuation">.</span>NewBalance<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>GrantRewardHandler<span class="token punctuation">)</span> <span class="token function">Validate</span><span class="token punctuation">(</span>action types<span class="token punctuation">.</span>Action<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">var</span> params GrantRewardParams</span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>action<span class="token punctuation">.</span>Params<span class="token punctuation">,</span> <span class="token operator">&amp;</span>params<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> err</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>Rewards<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"at least one reward required"</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> r <span class="token operator">:=</span> <span class="token keyword">range</span> params<span class="token punctuation">.</span>Rewards <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> r<span class="token punctuation">.</span>Type <span class="token operator">==</span> <span class="token string">""</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"reward type is required"</span><span class="token punctuation">)</span></span>
