<span class="line"></span>
<span class="line">    request <span class="token operator">:=</span> <span class="token operator">&amp;</span>notificationsvc<span class="token punctuation">.</span>SendNotificationRequest<span class="token punctuation">{</span></span>
<span class="line">        PlayerID<span class="token punctuation">:</span> input<span class="token punctuation">.</span>PlayerID<span class="token punctuation">,</span></span>
<span class="line">        Type<span class="token punctuation">:</span>     params<span class="token punctuation">.</span>Type<span class="token punctuation">,</span></span>
<span class="line">        Title<span class="token punctuation">:</span>    params<span class="token punctuation">.</span>Title<span class="token punctuation">,</span></span>
<span class="line">        Content<span class="token punctuation">:</span>  content<span class="token punctuation">,</span></span>
<span class="line">        Icon<span class="token punctuation">:</span>     params<span class="token punctuation">.</span>Icon<span class="token punctuation">,</span></span>
<span class="line">        Action<span class="token punctuation">:</span>   params<span class="token punctuation">.</span>Action<span class="token punctuation">,</span></span>
<span class="line">        Extra<span class="token punctuation">:</span>    params<span class="token punctuation">.</span>Extra<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    response<span class="token punctuation">,</span> err <span class="token operator">:=</span> h<span class="token punctuation">.</span>notificationSvc<span class="token punctuation">.</span><span class="token function">Send</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> request<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"send notification: %w"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>NotificationResult<span class="token punctuation">{</span></span>
<span class="line">        Success<span class="token punctuation">:</span>    response<span class="token punctuation">.</span>Success<span class="token punctuation">,</span></span>
<span class="line">        NotificationID<span class="token punctuation">:</span> response<span class="token punctuation">.</span>ID<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// replaceTemplateVariables 替换模板变量</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>SendNotificationHandler<span class="token punctuation">)</span> <span class="token function">replaceTemplateVariables</span><span class="token punctuation">(</span>content <span class="token builtin">string</span><span class="token punctuation">,</span> input <span class="token operator">*</span>engine<span class="token punctuation">.</span>ExecutionInput<span class="token punctuation">)</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 支持的变量:</span></span>
<span class="line">    <span class="token comment">// {player_id}, {player_name}, {level}, {vip_level}</span></span>
<span class="line">    <span class="token comment">// {campaign_name}, {reward_amount} 等</span></span>
<span class="line">    <span class="token comment">// TODO: 实现完整的模板变量替换</span></span>
<span class="line">    <span class="token keyword">return</span> content</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>SendNotificationHandler<span class="token punctuation">)</span> <span class="token function">Validate</span><span class="token punctuation">(</span>action types<span class="token punctuation">.</span>Action<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">var</span> params NotificationParams</span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Unmarshal</span><span class="token punctuation">(</span>action<span class="token punctuation">.</span>Params<span class="token punctuation">,</span> <span class="token operator">&amp;</span>params<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> err</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    validTypes <span class="token operator">:=</span> <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token builtin">bool</span><span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">"mail"</span><span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token string">"popup"</span><span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token string">"red_dot"</span><span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"toast"</span><span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token string">"center"</span><span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token string">"banner"</span><span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>validTypes<span class="token punctuation">[</span>params<span class="token punctuation">.</span>Type<span class="token punctuation">]</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"invalid notification type: %s"</span><span class="token punctuation">,</span> params<span class="token punctuation">.</span>Type<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> params<span class="token punctuation">.</span>Title <span class="token operator">==</span> <span class="token string">""</span> <span class="token operator">&amp;&amp;</span> params<span class="token punctuation">.</span>Content <span class="token operator">==</span> <span class="token string">""</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">"title or content is required"</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>SendNotificationHandler<span class="token punctuation">)</span> <span class="token function">ShouldRetry</span><span class="token punctuation">(</span>err <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token function">IsNetworkError</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> NotificationResult <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Success          <span class="token builtin">bool</span>   <span class="token string">`json:"success"`</span></span>
<span class="line">    NotificationID   <span class="token builtin">string</span> <span class="token string">`json:"notification_id"`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
