<h2 id="_4-集成-campaign-worker" tabindex="-1"><a class="header-anchor" href="#_4-集成-campaign-worker"><span>4. 集成：Campaign Worker</span></a></h2>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// cmd/campaign-worker/main.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"log/slog"</span></span>
<span class="line">    <span class="token string">"os"</span></span>
<span class="line">    <span class="token string">"os/signal"</span></span>
<span class="line">    <span class="token string">"syscall"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/cache"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/engine"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/repository"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/service"</span></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/event/worker"</span></span>
<span class="line">    <span class="token string">"github.com/redis/go-redis/v9"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 初始化</span></span>
<span class="line">    logger <span class="token operator">:=</span> slog<span class="token punctuation">.</span><span class="token function">Default</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Redis 客户端</span></span>
<span class="line">    redisClient <span class="token operator">:=</span> redis<span class="token punctuation">.</span><span class="token function">NewClient</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>redis<span class="token punctuation">.</span>Options<span class="token punctuation">{</span></span>
<span class="line">        Addr<span class="token punctuation">:</span> <span class="token function">getEnv</span><span class="token punctuation">(</span><span class="token string">"REDIS_ADDR"</span><span class="token punctuation">,</span> <span class="token string">"localhost:6379"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 依赖注入</span></span>
<span class="line">    campaignRepo <span class="token operator">:=</span> repository<span class="token punctuation">.</span><span class="token function">NewPostgresRepository</span><span class="token punctuation">(</span><span class="token function">getEnv</span><span class="token punctuation">(</span><span class="token string">"DATABASE_URL"</span><span class="token punctuation">,</span> <span class="token string">""</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    campaignCache <span class="token operator">:=</span> cache<span class="token punctuation">.</span><span class="token function">NewRedisCache</span><span class="token punctuation">(</span>redisClient<span class="token punctuation">)</span></span>
<span class="line">    playerSvc <span class="token operator">:=</span> service<span class="token punctuation">.</span><span class="token function">NewPlayerService</span><span class="token punctuation">(</span>campaignRepo<span class="token punctuation">)</span></span>
<span class="line">    gameClient <span class="token operator">:=</span> service<span class="token punctuation">.</span><span class="token function">NewGameServiceClient</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    notificationSvc <span class="token operator">:=</span> service<span class="token punctuation">.</span><span class="token function">NewNotificationService</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    progressRepo <span class="token operator">:=</span> repository<span class="token punctuation">.</span><span class="token function">NewProgressRepository</span><span class="token punctuation">(</span><span class="token function">getEnv</span><span class="token punctuation">(</span><span class="token string">"DATABASE_URL"</span><span class="token punctuation">,</span> <span class="token string">""</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 频率限制器</span></span>
<span class="line">    freqLimiter <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">NewRedisFrequencyLimiter</span><span class="token punctuation">(</span>redisClient<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 创建核心组件</span></span>
<span class="line">    triggerMatcher <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">NewTriggerMatcher</span><span class="token punctuation">(</span>campaignCache<span class="token punctuation">,</span> playerSvc<span class="token punctuation">,</span> freqLimiter<span class="token punctuation">)</span></span>
<span class="line">    conditionEvaluator <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">NewConditionEvaluator</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    actionExecutor <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">NewActionExecutor</span><span class="token punctuation">(</span>progressRepo<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 注册外部服务处理器</span></span>
<span class="line">    actionExecutor<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"grant_reward"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>actions<span class="token punctuation">.</span>GrantRewardHandler<span class="token punctuation">{</span>gameClient<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    actionExecutor<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span><span class="token string">"send_notification"</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>actions<span class="token punctuation">.</span>SendNotificationHandler<span class="token punctuation">{</span>notificationSvc<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 创建活动处理器</span></span>
<span class="line">    campaignHandler <span class="token operator">:=</span> <span class="token function">NewCampaignHandler</span><span class="token punctuation">(</span></span>
<span class="line">        triggerMatcher<span class="token punctuation">,</span></span>
<span class="line">        conditionEvaluator<span class="token punctuation">,</span></span>
<span class="line">        actionExecutor<span class="token punctuation">,</span></span>
<span class="line">        campaignRepo<span class="token punctuation">,</span></span>
<span class="line">        progressRepo<span class="token punctuation">,</span></span>
<span class="line">        logger<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 创建事件 Worker</span></span>
<span class="line">    eventWorkerConfig <span class="token operator">:=</span> worker<span class="token punctuation">.</span>WorkerConfig<span class="token punctuation">{</span></span>
<span class="line">        RedisURL<span class="token punctuation">:</span>       <span class="token function">getEnv</span><span class="token punctuation">(</span><span class="token string">"REDIS_URL"</span><span class="token punctuation">,</span> <span class="token string">"redis://localhost:6379/0"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        StreamEvents<span class="token punctuation">:</span>   <span class="token string">"events"</span><span class="token punctuation">,</span></span>
<span class="line">        StreamHighPrio<span class="token punctuation">:</span> <span class="token string">"events:high_priority"</span><span class="token punctuation">,</span></span>
<span class="line">        StreamDLQ<span class="token punctuation">:</span>      <span class="token string">"events:dlq"</span><span class="token punctuation">,</span></span>
<span class="line">        ConsumerGroup<span class="token punctuation">:</span>  <span class="token string">"campaign-group"</span><span class="token punctuation">,</span></span>
<span class="line">        ConsumerName<span class="token punctuation">:</span>   <span class="token string">"campaign-worker-"</span> <span class="token operator">+</span> <span class="token function">generateID</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        BatchSize<span class="token punctuation">:</span>      <span class="token number">50</span><span class="token punctuation">,</span></span>
<span class="line">        BlockTime<span class="token punctuation">:</span>      <span class="token number">1</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line">        FlushInterval<span class="token punctuation">:</span>  <span class="token number">5</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line">        MaxRetries<span class="token punctuation">:</span>     <span class="token number">5</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    eventWorker <span class="token operator">:=</span> worker<span class="token punctuation">.</span><span class="token function">NewWorker</span><span class="token punctuation">(</span>eventWorkerConfig<span class="token punctuation">)</span></span>
<span class="line">    eventWorker<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span>campaignHandler<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 启动</span></span>
<span class="line">    ctx<span class="token punctuation">,</span> cancel <span class="token operator">:=</span> signal<span class="token punctuation">.</span><span class="token function">NotifyContext</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> os<span class="token punctuation">.</span>Interrupt<span class="token punctuation">,</span> syscall<span class="token punctuation">.</span>SIGTERM<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">defer</span> <span class="token function">cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">"campaign-worker starting"</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">:=</span> eventWorker<span class="token punctuation">.</span><span class="token function">Start</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">"worker start failed"</span><span class="token punctuation">,</span> <span class="token string">"error"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">        os<span class="token punctuation">.</span><span class="token function">Exit</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token operator">&lt;-</span>ctx<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">"campaign-worker shutting down"</span><span class="token punctuation">)</span></span>
<span class="line">    eventWorker<span class="token punctuation">.</span><span class="token function">Stop</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">"campaign-worker stopped"</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// CampaignHandler 活动事件处理器</span></span>
<span class="line"><span class="token keyword">type</span> CampaignHandler <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    matcher   <span class="token operator">*</span>engine<span class="token punctuation">.</span>TriggerMatcher</span>
<span class="line">    evaluator <span class="token operator">*</span>engine<span class="token punctuation">.</span>ConditionEvaluator</span>
<span class="line">    executor  <span class="token operator">*</span>engine<span class="token punctuation">.</span>ActionExecutor</span>
<span class="line">    repo      repository<span class="token punctuation">.</span>CampaignRepository</span>
<span class="line">    progress  repository<span class="token punctuation">.</span>ProgressRepository</span>
<span class="line">    logger    <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewCampaignHandler</span><span class="token punctuation">(</span></span>
<span class="line">    matcher <span class="token operator">*</span>engine<span class="token punctuation">.</span>TriggerMatcher<span class="token punctuation">,</span></span>
<span class="line">    evaluator <span class="token operator">*</span>engine<span class="token punctuation">.</span>ConditionEvaluator<span class="token punctuation">,</span></span>
<span class="line">    executor <span class="token operator">*</span>engine<span class="token punctuation">.</span>ActionExecutor<span class="token punctuation">,</span></span>
<span class="line">    repo repository<span class="token punctuation">.</span>CampaignRepository<span class="token punctuation">,</span></span>
<span class="line">    progress repository<span class="token punctuation">.</span>ProgressRepository<span class="token punctuation">,</span></span>
<span class="line">    logger <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token operator">*</span>CampaignHandler <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>CampaignHandler<span class="token punctuation">{</span></span>
<span class="line">        matcher<span class="token punctuation">:</span>   matcher<span class="token punctuation">,</span></span>
<span class="line">        evaluator<span class="token punctuation">:</span> evaluator<span class="token punctuation">,</span></span>
<span class="line">        executor<span class="token punctuation">:</span>  executor<span class="token punctuation">,</span></span>
<span class="line">        repo<span class="token punctuation">:</span>      repo<span class="token punctuation">,</span></span>
<span class="line">        progress<span class="token punctuation">:</span>  progress<span class="token punctuation">,</span></span>
<span class="line">        logger<span class="token punctuation">:</span>    logger<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>CampaignHandler<span class="token punctuation">)</span> <span class="token function">GetEventTypes</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 返回所有感兴趣的事件类型</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">"player.login"</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"player.register"</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"payment.success"</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"quest.complete"</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">"level.up"</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token comment">// ...</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>h <span class="token operator">*</span>CampaignHandler<span class="token punctuation">)</span> <span class="token function">Handle</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> event worker<span class="token punctuation">.</span>Event<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">    startTime <span class="token operator">:=</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    logger <span class="token operator">:=</span> h<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">With</span><span class="token punctuation">(</span><span class="token string">"event_type"</span><span class="token punctuation">,</span> event<span class="token punctuation">[</span><span class="token string">"event_type"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string">"player_id"</span><span class="token punctuation">,</span> event<span class="token punctuation">[</span><span class="token string">"player_id"</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 转换事件</span></span>
<span class="line">    campaignEvent <span class="token operator">:=</span> h<span class="token punctuation">.</span><span class="token function">convertEvent</span><span class="token punctuation">(</span>event<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 1. 触发器匹配</span></span>
<span class="line">    matches<span class="token punctuation">,</span> err <span class="token operator">:=</span> h<span class="token punctuation">.</span>matcher<span class="token punctuation">.</span><span class="token function">Match</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> campaignEvent<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">"trigger_match_failed"</span><span class="token punctuation">,</span> <span class="token string">"error"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> err</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>matches<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        logger<span class="token punctuation">.</span><span class="token function">Debug</span><span class="token punctuation">(</span><span class="token string">"no_campaigns_matched"</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">"campaigns_matched"</span><span class="token punctuation">,</span> <span class="token string">"count"</span><span class="token punctuation">,</span> <span class="token function">len</span><span class="token punctuation">(</span>matches<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
