<span class="line">        <span class="token keyword">if</span> err <span class="token operator">:=</span> h<span class="token punctuation">.</span><span class="token function">processMatchedCampaign</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> match<span class="token punctuation">,</span> campaignEvent<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">            logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">"process_campaign_failed"</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"campaign_id"</span><span class="token punctuation">,</span> match<span class="token punctuation">.</span>CampaignID<span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">"error"</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
