<span class="line">    logger <span class="token operator">:=</span> h<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">With</span><span class="token punctuation">(</span><span class="token string">"campaign_id"</span><span class="token punctuation">,</span> match<span class="token punctuation">.</span>CampaignID<span class="token punctuation">)</span></span>
