<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>passed <span class="token punctuation">{</span></span>
<span class="line">        logger<span class="token punctuation">.</span><span class="token function">Debug</span><span class="token punctuation">(</span><span class="token string">"conditions_not_met"</span><span class="token punctuation">)</span></span>
