<h2 id="_5-性能优化" tabindex="-1"><a class="header-anchor" href="#_5-性能优化"><span>5. 性能优化</span></a></h2>
<h3 id="_5-1-批处理优化" tabindex="-1"><a class="header-anchor" href="#_5-1-批处理优化"><span>5.1 批处理优化</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// BatchProcessor 批处理器</span></span>
<span class="line"><span class="token keyword">type</span> BatchProcessor <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    buffer    <span class="token punctuation">[</span><span class="token punctuation">]</span>Event</span>
<span class="line">    maxSize   <span class="token builtin">int</span></span>
<span class="line">    flushInterval time<span class="token punctuation">.</span>Duration</span>
<span class="line">    processor <span class="token keyword">func</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> events <span class="token punctuation">[</span><span class="token punctuation">]</span>Event<span class="token punctuation">)</span> <span class="token builtin">error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>bp <span class="token operator">*</span>BatchProcessor<span class="token punctuation">)</span> <span class="token function">Add</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> event Event<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">    bp<span class="token punctuation">.</span>buffer <span class="token operator">=</span> <span class="token function">append</span><span class="token punctuation">(</span>bp<span class="token punctuation">.</span>buffer<span class="token punctuation">,</span> event<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>bp<span class="token punctuation">.</span>buffer<span class="token punctuation">)</span> <span class="token operator">>=</span> bp<span class="token punctuation">.</span>maxSize <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> bp<span class="token punctuation">.</span><span class="token function">flush</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>bp <span class="token operator">*</span>BatchProcessor<span class="token punctuation">)</span> <span class="token function">flush</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">len</span><span class="token punctuation">(</span>bp<span class="token punctuation">.</span>buffer<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    events <span class="token operator">:=</span> bp<span class="token punctuation">.</span>buffer</span>
<span class="line">    bp<span class="token punctuation">.</span>buffer <span class="token operator">=</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>Event<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> bp<span class="token punctuation">.</span>maxSize<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> bp<span class="token punctuation">.</span><span class="token function">processor</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> events<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-缓存策略" tabindex="-1"><a class="header-anchor" href="#_5-2-缓存策略"><span>5.2 缓存策略</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// CachedMatcher 带缓存的匹配器</span></span>
<span class="line"><span class="token keyword">type</span> CachedMatcher <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    inner   engine<span class="token punctuation">.</span>Matcher</span>
<span class="line">    cache   <span class="token operator">*</span>lru<span class="token punctuation">.</span>Cache</span>
<span class="line">    ttl     time<span class="token punctuation">.</span>Duration</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>cm <span class="token operator">*</span>CachedMatcher<span class="token punctuation">)</span> <span class="token function">Match</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> event engine<span class="token punctuation">.</span>Event<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>engine<span class="token punctuation">.</span>MatchResult<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 生成缓存键</span></span>
<span class="line">    key <span class="token operator">:=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"%s:%s:%s"</span><span class="token punctuation">,</span> event<span class="token punctuation">.</span>GameID<span class="token punctuation">,</span> event<span class="token punctuation">.</span>Env<span class="token punctuation">,</span> event<span class="token punctuation">.</span>EventType<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 尝试从缓存获取</span></span>
<span class="line">    <span class="token keyword">if</span> cached<span class="token punctuation">,</span> ok <span class="token operator">:=</span> cm<span class="token punctuation">.</span>cache<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span> ok <span class="token punctuation">{</span></span>
<span class="line">        campaigns <span class="token operator">:=</span> cached<span class="token punctuation">.</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">*</span>types<span class="token punctuation">.</span>CampaignInstance<span class="token punctuation">)</span></span>
<span class="line">        <span class="token comment">// 过滤并返回匹配结果</span></span>
<span class="line">        <span class="token keyword">return</span> cm<span class="token punctuation">.</span><span class="token function">filterMatched</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> campaigns<span class="token punctuation">,</span> event<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 从源获取</span></span>
<span class="line">    results<span class="token punctuation">,</span> err <span class="token operator">:=</span> cm<span class="token punctuation">.</span>inner<span class="token punctuation">.</span><span class="token function">Match</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> event<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> err</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 缓存结果</span></span>
<span class="line">    cm<span class="token punctuation">.</span>cache<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span>key<span class="token punctuation">,</span> results<span class="token punctuation">,</span> cm<span class="token punctuation">.</span>ttl<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> results<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-3-指标收集" tabindex="-1"><a class="header-anchor" href="#_5-3-指标收集"><span>5.3 指标收集</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// MetricsCollector 指标收集器</span></span>
<span class="line"><span class="token keyword">type</span> MetricsCollector <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    matcherCounter   prometheus<span class="token punctuation">.</span>Counter</span>
<span class="line">    evaluatorCounter prometheus<span class="token punctuation">.</span>Counter</span>
<span class="line">    executorCounter  prometheus<span class="token punctuation">.</span>Counter</span>
<span class="line">    executorDuration prometheus<span class="token punctuation">.</span>Histogram</span>
<span class="line">    executorErrors   prometheus<span class="token punctuation">.</span>Counter</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>mc <span class="token operator">*</span>MetricsCollector<span class="token punctuation">)</span> <span class="token function">RecordExecution</span><span class="token punctuation">(</span>output <span class="token operator">*</span>engine<span class="token punctuation">.</span>ExecutionOutput<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    mc<span class="token punctuation">.</span>executorCounter<span class="token punctuation">.</span><span class="token function">Inc</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    mc<span class="token punctuation">.</span>executorDuration<span class="token punctuation">.</span><span class="token function">Observe</span><span class="token punctuation">(</span><span class="token function">float64</span><span class="token punctuation">(</span>output<span class="token punctuation">.</span>DurationMs<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>output<span class="token punctuation">.</span>Success <span class="token punctuation">{</span></span>
<span class="line">        mc<span class="token punctuation">.</span>executorErrors<span class="token punctuation">.</span><span class="token function">Inc</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> result <span class="token operator">:=</span> <span class="token keyword">range</span> output<span class="token punctuation">.</span>Results <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> result<span class="token punctuation">.</span>Skipped <span class="token punctuation">{</span></span>
<span class="line">            skippedCounter<span class="token punctuation">.</span><span class="token function">WithLabelValues</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>ActionType<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Inc</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token operator">!</span>result<span class="token punctuation">.</span>Success <span class="token punctuation">{</span></span>
<span class="line">            errorCounter<span class="token punctuation">.</span><span class="token function">WithLabelValues</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>ActionType<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Inc</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
