<h2 id="_6-测试示例" tabindex="-1"><a class="header-anchor" href="#_6-测试示例"><span>6. 测试示例</span></a></h2>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token comment">// internal/campaign/engine/trigger_matcher_test.go</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">package</span> engine</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"testing"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"github.com/cuihairu/croupier/internal/campaign/types"</span></span>
<span class="line">    <span class="token string">"github.com/stretchr/testify/assert"</span></span>
<span class="line">    <span class="token string">"github.com/stretchr/testify/mock"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">TestTriggerMatcher_Match</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Mock 依赖</span></span>
<span class="line">    mockCache <span class="token operator">:=</span> <span class="token function">new</span><span class="token punctuation">(</span>MockCampaignCache<span class="token punctuation">)</span></span>
<span class="line">    mockPlayerSvc <span class="token operator">:=</span> <span class="token function">new</span><span class="token punctuation">(</span>MockPlayerService<span class="token punctuation">)</span></span>
<span class="line">    mockFreqLimiter <span class="token operator">:=</span> <span class="token function">new</span><span class="token punctuation">(</span>MockFrequencyLimiter<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    matcher <span class="token operator">:=</span> <span class="token function">NewTriggerMatcher</span><span class="token punctuation">(</span>mockCache<span class="token punctuation">,</span> mockPlayerSvc<span class="token punctuation">,</span> mockFreqLimiter<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 准备测试数据</span></span>
<span class="line">    event <span class="token operator">:=</span> Event<span class="token punctuation">{</span></span>
<span class="line">        EventType<span class="token punctuation">:</span>  <span class="token string">"player.login"</span><span class="token punctuation">,</span></span>
<span class="line">        PlayerID<span class="token punctuation">:</span>   <span class="token string">"player123"</span><span class="token punctuation">,</span></span>
<span class="line">        GameID<span class="token punctuation">:</span>     <span class="token string">"game1"</span><span class="token punctuation">,</span></span>
<span class="line">        Env<span class="token punctuation">:</span>        <span class="token string">"prod"</span><span class="token punctuation">,</span></span>
<span class="line">        EventTime<span class="token punctuation">:</span>  time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        Platform<span class="token punctuation">:</span>   <span class="token string">"ios"</span><span class="token punctuation">,</span></span>
<span class="line">        Properties<span class="token punctuation">:</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    campaign <span class="token operator">:=</span> <span class="token operator">&amp;</span>types<span class="token punctuation">.</span>CampaignInstance<span class="token punctuation">{</span></span>
<span class="line">        ID<span class="token punctuation">:</span>       <span class="token string">"campaign1"</span><span class="token punctuation">,</span></span>
